ALTER TABLE public.detector_findings ADD COLUMN IF NOT EXISTS resolution jsonb NOT NULL DEFAULT '{}';
ALTER TABLE public.detector_findings ADD COLUMN IF NOT EXISTS resolved_at timestamptz;
CREATE TABLE public.detection_observations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_id uuid REFERENCES public.objects(id),owner_id uuid NOT NULL,facts jsonb NOT NULL,evidence_refs uuid[] NOT NULL DEFAULT '{}',rationale text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days');
GRANT SELECT ON public.detection_observations TO authenticated; GRANT ALL ON public.detection_observations TO service_role; ALTER TABLE public.detection_observations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read scoped observations" ON public.detection_observations FOR SELECT TO authenticated USING ((owner_id=auth.uid() OR public.has_role(auth.uid(),'steward')) AND (subject_id IS NULL OR EXISTS(SELECT 1 FROM public.objects WHERE id=subject_id)) AND NOT EXISTS(SELECT 1 FROM unnest(evidence_refs) e WHERE NOT EXISTS(SELECT 1 FROM public.objects WHERE id=e)));
CREATE OR REPLACE FUNCTION public.detection_catalogue() RETURNS TABLE(key text,family text,fact text,remediation text) LANGUAGE sql IMMUTABLE AS $$ SELECT v.key,v.family,v.fact,'Restore the violated evidence condition; record the resolution.' FROM(VALUES
('RequestedSolutionWithoutCondition','valueos','requested_solution_without_condition'),('MissionWithoutEmpoweredCoCreator','valueos','mission_without_empowered_co_creator'),('DocumentPreparedForHandoff','valueos','document_prepared_for_handoff'),('AwarenessOnlyRecurringMeeting','valueos','awareness_only_recurring_meeting'),('StandardWorkAwaitingApproval','valueos','standard_work_awaiting_approval'),('CapabilityCreatedWithoutRegistrySearch','valueos','capability_created_without_registry_search'),('BatchThatCouldBeIncremental','valueos','batch_that_could_be_incremental'),('HumanMonitoringMachinesCouldPerform','valueos','human_monitoring_machines_could_perform'),('AutonomousActionWithoutEvidence','valueos','autonomous_action_without_evidence'),('CapabilityWithoutOwnerTelemetryOrExpiration','valueos','capability_without_owner_telemetry_or_expiration'),('LocalScopeOverEnterpriseValue','valueos','local_scope_over_enterprise_value'),('BuilderPerformingAgentWork','valueos','builder_performing_agent_work'),('UncitableGeneratedAnswer','valueos','uncitable_generated_answer'),('HighImpactToolCallWithoutPolicy','valueos','high_impact_tool_call_without_policy'),('ValueFeedDriftingTowardEngagement','valueos','value_feed_drifting_toward_engagement'),
('CanonFragmentation','thread','canon_fragmentation'),('ScopeChangeClassifiedAsCosmetic','thread','scope_change_classified_as_cosmetic'),('RejectedMeasureInUse','thread','rejected_measure_in_use'),('WikiDrift','thread','wiki_drift'),('AuthorityInflation','thread','authority_inflation'),('ProhibitedInference','thread','prohibited_inference'),
('RawSpeechTreatedAsAuthority','framing','raw_speech_treated_as_authority'),('UnextractedDecision','framing','unextracted_decision'),('BehaviorWithoutNeed','framing','behavior_without_need'),('NeedWithoutBehavior','framing','need_without_behavior'),('NeedWithoutMeasure','framing','need_without_measure'),('UnextractedSession','framing','unextracted_session'),('SessionWithoutConsent','framing','session_without_consent'),('ContradictionUnresolved','framing','contradiction_unresolved'),('AssumptionUnverified','framing','assumption_unverified'),('ProvenanceSpanMissing','framing','provenance_span_missing'),('DraftObjectUsedAsBasis','framing','draft_object_used_as_basis'),('DraftCountedAsProgress','framing','draft_counted_as_progress'),('SessionProducingMinutes','framing','session_producing_minutes'),('DependencyCycle','framing','dependency_cycle'),('InferredEdgeAutoConfirmed','framing','inferred_edge_auto_confirmed'),('FramingSessionAsMeeting','framing','framing_session_as_meeting')) v(key,family,fact) $$;
CREATE OR REPLACE FUNCTION public._rejected_measure(t text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT coalesce(t,'') ~* '(story[ _-]?points|sprint[ _-]?velocity|requirements[ _-]?completed|features[ _-]?shipped[ _-]?without[ _-]?outcome[ _-]?evidence|lines[ _-]?of[ _-]?code|prompt[ _-]?count|agent[ _-]?call[ _-]?count|utili[sz]ation[ _-]?as[ _-]?a[ _-]?proxy[ _-]?for[ _-]?value|meetings[ _-]?held|documents[ _-]?produced|training[ _-]?modules[ _-]?completed)' $$;
CREATE OR REPLACE FUNCTION public._phase10_register() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE own uuid; BEGIN SELECT user_id INTO own FROM public.user_roles WHERE role='steward' ORDER BY user_id LIMIT 1; IF own IS NULL THEN RAISE EXCEPTION 'OWNER_REQUIRED'; END IF; INSERT INTO public.detectors(key,family,owner_id,schedule,event_triggers,params,version) SELECT key,family,own,'0 * * * *',ARRAY['object.changed','edge.changed','rendition.changed','observation.changed'],jsonb_build_object('fact',fact,'query','detection_candidates','threshold',true,'owner_role','steward','remediation_hint',remediation,'semantic_basis','explicit evidence observations or typed graph conditions'),'1.0.0' FROM public.detection_catalogue() ON CONFLICT(key) DO UPDATE SET schedule=excluded.schedule,event_triggers=excluded.event_triggers,params=public.detectors.params||excluded.params; END $$;
CREATE OR REPLACE FUNCTION public.detection_candidates() RETURNS TABLE(detector_key text,object_id uuid,severity text,evidence jsonb) LANGUAGE sql STABLE SET search_path=public AS $$
SELECT c.key,d.subject_id,'high',jsonb_build_object('observation_id',d.id,'owner_id',d.owner_id,'evidence_refs',d.evidence_refs,'explanation',d.rationale,'source','explicit_observation') FROM public.detection_observations d CROSS JOIN public.detection_catalogue() c WHERE d.expires_at>now() AND d.facts->c.fact='true'::jsonb
UNION ALL SELECT c.key,o.id,'high',jsonb_build_object('ref',o.human_ref,'explanation','Typed operating evidence violates '||c.key,'source','graph') FROM public.objects o CROSS JOIN public.detection_catalogue() c WHERE NOT o.is_tombstone AND CASE c.key
WHEN 'RequestedSolutionWithoutCondition' THEN o.type IN('ValueSignal','ValueMission') AND coalesce(o.body->'requested_solution_candidates','[]')<>'[]'::jsonb AND (coalesce(o.body->>'observed_condition',o.body->>'measurable_condition','')='' OR coalesce(o.body->>'baseline_performance',o.body->>'baseline',o.body->>'magnitude','')='')
WHEN 'MissionWithoutEmpoweredCoCreator' THEN o.type='ValueMission' AND o.lifecycle_state NOT IN('framing','proposed','stopped','retired') AND (coalesce(o.body->>'co_creator','')='' OR coalesce(o.body->>'decision_authority','')='')
WHEN 'DocumentPreparedForHandoff' THEN (o.title||' '||o.statement) ~* '(document.{0,40}(handoff|hand.off|hand.over)|(handoff|hand.off).{0,40}document)'
WHEN 'AwarenessOnlyRecurringMeeting' THEN o.body->>'recurring'='true' AND o.body->>'purpose_kind'='awareness'
WHEN 'StandardWorkAwaitingApproval' THEN o.type<>'HumanDecisionRequest' AND o.lifecycle_state ~* '(awaiting.approval|pending.sign.off|submitted.for.review|in.qa.phase)'
WHEN 'BatchThatCouldBeIncremental' THEN o.type IN('ExposureAuthorization','ExposurePopulation') AND coalesce(o.body->>'percent',o.body->'exposure_population'->>'percent')='100' AND o.body->>'incremental_available'='true'
WHEN 'HumanMonitoringMachinesCouldPerform' THEN o.body->>'operation_kind'='observation' AND o.body->>'machine_executable'='true' AND o.body->>'performed_by_kind'='human'
WHEN 'AutonomousActionWithoutEvidence' THEN o.type IN('ComposableCapability','WorkingCapability') AND o.authority_level='autonomous_with_exception' AND cardinality(o.evidence_refs)=0
WHEN 'CapabilityWithoutOwnerTelemetryOrExpiration' THEN o.type IN('ComposableCapability','WorkingCapability') AND o.lifecycle_state IN('published','limited_exposure','producing_value') AND (o.owner_id IS NULL OR coalesce(o.body->>'cost_resource_telemetry_ref','')='' OR o.review_date IS NULL OR o.expiration_condition='{}')
WHEN 'LocalScopeOverEnterpriseValue' THEN o.type IN('ComposableCapability','ConfirmedDecision') AND o.body->>'enterprise_outcome_conflict'='true'
WHEN 'BuilderPerformingAgentWork' THEN o.body->>'performed_by_role'='builder' AND o.body->>'repeated_mechanical'='true' AND o.body->>'machine_executable'='true'
WHEN 'HighImpactToolCallWithoutPolicy' THEN o.body->>'material_tool_effect'='true' AND NOT EXISTS(SELECT 1 FROM public.objects p WHERE p.type='PolicyEvaluation' AND NOT p.is_tombstone AND p.body->>'subject_ref'=o.id::text AND p.body->>'deterministic'='true')
WHEN 'ValueFeedDriftingTowardEngagement' THEN o.body->>'visibility_rewards'='true'
WHEN 'RejectedMeasureInUse' THEN public._rejected_measure(o.title||' '||o.statement||' '||o.body::text)
WHEN 'AuthorityInflation' THEN o.body->>'authority_exceeds_evidence'='true'
WHEN 'ProhibitedInference' THEN public._prohibited_inference(o.title||' '||o.statement) IS NOT NULL
ELSE false END
UNION ALL SELECT 'CapabilityCreatedWithoutRegistrySearch',r.object_id,'critical',jsonb_build_object('explanation','Build has no linked reuse check.','source','graph') FROM public.build_runs r LEFT JOIN public.creation_prompts cp ON cp.object_id=r.prompt_id WHERE cp.reuse_check_id IS NULL
UNION ALL SELECT 'UncitableGeneratedAnswer',NULL::uuid,'high',jsonb_build_object('rendition_id',r.id,'owner_id',r.permission_context->>'actor','explanation','Live guidance has no authoritative citation.','source','rendition') FROM public.renditions r WHERE r.state='live' AND (r.citations IS NULL OR r.citations IN('[]','{}'))
UNION ALL SELECT 'CanonFragmentation',a.id,'high',jsonb_build_object('ref',a.human_ref,'conflicting_ref',b.human_ref,'evidence_refs',jsonb_build_array(a.id,b.id),'explanation','Active definitions differ in the same named scope.','source','graph') FROM public.objects a JOIN public.objects b ON a.id<b.id AND a.title=b.title AND a.type=b.type AND coalesce(a.body->>'scope','')=coalesce(b.body->>'scope','') JOIN public.object_type_registry t ON t.type=a.type AND t.family='Canon' WHERE NOT a.is_tombstone AND NOT b.is_tombstone AND a.lifecycle_state='active' AND b.lifecycle_state='active' AND coalesce(a.body->>'definition',a.body->>'rule_statement',a.statement)<>coalesce(b.body->>'definition',b.body->>'rule_statement',b.statement)
UNION ALL SELECT 'ScopeChangeClassifiedAsCosmetic',i.object_id,'high',jsonb_build_object('explanation','Iteration scope change declared under a lower class.','source','iteration') FROM public.iterations i WHERE i.scope_change_flag $$;
CREATE OR REPLACE FUNCTION public.thread_detection_sweep(p_actor jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x record; nn int:=0; nr int:=0; seq bigint; BEGIN PERFORM public._assert_actor(p_actor); PERFORM public._phase10_register(); PERFORM pg_advisory_xact_lock(hashtext('thread-detection-sweep')); PERFORM set_config('thread.detection_sweeping','on',true);
UPDATE public.detector_findings SET state='open',accepted_by=NULL,accepted_until=NULL,resolution=resolution||jsonb_build_object('expired_acceptance_at',now()) WHERE state='accepted_risk' AND accepted_until<=now();
PERFORM public.thread_graph_sweep(p_actor); PERFORM public.thread_framing_sweep(p_actor);
UPDATE public.detector_findings f SET state='resolved',resolved_at=now(),resolution=jsonb_build_object('kind','condition_cleared','at',now()) WHERE f.state='open' AND f.evidence->>'phase10'='true' AND NOT EXISTS(SELECT 1 FROM public.detection_candidates() c WHERE c.detector_key=f.detector_key AND c.object_id IS NOT DISTINCT FROM f.object_id AND coalesce(c.evidence->>'observation_id',c.evidence->>'rendition_id','')=coalesce(f.evidence->>'observation_id',f.evidence->>'rendition_id','')); GET DIAGNOSTICS nr=ROW_COUNT;
FOR x IN SELECT DISTINCT ON(c.detector_key,c.object_id,coalesce(c.evidence->>'observation_id',c.evidence->>'rendition_id','')) c.*,d.owner_id FROM public.detection_candidates() c JOIN public.detectors d ON d.key=c.detector_key LOOP
IF NOT EXISTS(SELECT 1 FROM public.detector_findings f WHERE f.detector_key=x.detector_key AND f.object_id IS NOT DISTINCT FROM x.object_id AND f.state IN('open','accepted_risk') AND coalesce(f.evidence->>'observation_id',f.evidence->>'rendition_id','')=coalesce(x.evidence->>'observation_id',x.evidence->>'rendition_id','')) THEN INSERT INTO public.detector_findings(id,detector_key,object_id,severity,owner_id,state,evidence) VALUES(public.uuid_v7(),x.detector_key,x.object_id,x.severity,x.owner_id,'open',x.evidence||jsonb_build_object('phase10',true)); nn:=nn+1; END IF; END LOOP;
seq:=public._mcp_ledger(p_actor,'detector.sweep.phase10',NULL,jsonb_build_object('new',nn,'resolved',nr)); PERFORM set_config('thread.detection_sweeping','off',true); RETURN jsonb_build_object('new',nn,'resolved',nr,'ledger_seq',seq,'computed_at',now()); END $$;
CREATE OR REPLACE FUNCTION public.thread_observe_detection(p_actor jsonb,p_subject uuid,p_facts jsonb,p_evidence uuid[],p_rationale text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; oid uuid; BEGIN PERFORM public._assert_actor(p_actor); uid:=(p_actor->>'id')::uuid; IF p_actor->>'kind'<>'human' OR NOT public._is_current_member(uid) THEN RAISE EXCEPTION 'HUMAN_MEMBER_REQUIRED'; END IF;
IF length(btrim(p_rationale))<3 OR jsonb_typeof(p_facts)<>'object' THEN RAISE EXCEPTION 'EVIDENCE_REQUIRED'; END IF;
IF p_subject IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.objects o WHERE o.id=p_subject AND public._can_read_as(uid,o.permission,o.data_classification)) THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
IF EXISTS(SELECT 1 FROM unnest(p_evidence) e WHERE NOT EXISTS(SELECT 1 FROM public.objects o WHERE o.id=e AND public._can_read_as(uid,o.permission,o.data_classification))) THEN RAISE EXCEPTION 'EVIDENCE_NOT_VISIBLE'; END IF;
IF EXISTS(SELECT 1 FROM jsonb_each(p_facts) kv WHERE kv.value NOT IN('true','false') OR NOT EXISTS(SELECT 1 FROM public.detection_catalogue() c WHERE c.fact=kv.key)) THEN RAISE EXCEPTION 'INVALID_FACT'; END IF;
INSERT INTO public.detection_observations(subject_id,owner_id,facts,evidence_refs,rationale) VALUES(p_subject,uid,p_facts,p_evidence,p_rationale) RETURNING id INTO oid; PERFORM public._mcp_ledger(p_actor,'detector.observation',p_subject,jsonb_build_object('observation_id',oid,'evidence_refs',p_evidence)); RETURN public.thread_detection_sweep(p_actor)||jsonb_build_object('observation_id',oid); END $$;
CREATE OR REPLACE FUNCTION public.thread_resolve_finding(p_actor jsonb,p_finding uuid,p_resolution text,p_accept_until timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.detector_findings; uid uuid; seq bigint; BEGIN PERFORM public._assert_actor(p_actor); uid:=(p_actor->>'id')::uuid; SELECT * INTO f FROM public.detector_findings WHERE id=p_finding FOR UPDATE; IF f.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; IF f.owner_id<>uid AND NOT public.has_role(uid,'steward') THEN RAISE EXCEPTION 'FINDING_OWNER_REQUIRED'; END IF; IF p_actor->>'kind'<>'human' AND p_accept_until IS NOT NULL THEN RAISE EXCEPTION 'HUMAN_APPROVER_REQUIRED'; END IF; IF f.object_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.objects o WHERE o.id=f.object_id AND public._can_read_as(uid,o.permission,o.data_classification)) THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; IF length(btrim(p_resolution))<3 THEN RAISE EXCEPTION 'RESOLUTION_REQUIRED'; END IF; IF p_accept_until IS NOT NULL AND p_accept_until<=now() THEN RAISE EXCEPTION 'FUTURE_EXPIRY_REQUIRED'; END IF;
UPDATE public.detector_findings SET state=CASE WHEN p_accept_until IS NULL THEN 'resolved' ELSE 'accepted_risk' END,accepted_by=CASE WHEN p_accept_until IS NOT NULL THEN uid END,accepted_until=p_accept_until,resolved_at=CASE WHEN p_accept_until IS NULL THEN now() END,resolution=jsonb_build_object('explanation',p_resolution,'actor',p_actor,'at',now()) WHERE id=f.id;
seq:=public._mcp_ledger(p_actor,'detector.finding.resolved',f.object_id,jsonb_build_object('finding_id',f.id,'accepted_until',p_accept_until,'resolution',p_resolution)); RETURN jsonb_build_object('ledger_seq',seq); END $$;
CREATE OR REPLACE FUNCTION public._phase10_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF current_setting('thread.detection_sweeping',true) IS DISTINCT FROM 'on' AND EXISTS(SELECT 1 FROM public.user_roles WHERE role='steward') THEN PERFORM public.thread_detection_sweep('{"kind":"system","id":"phase10-event","authority_used":"observe"}'); END IF; RETURN NULL; END $$;
CREATE TRIGGER phase10_object_event AFTER INSERT OR UPDATE ON public.objects FOR EACH STATEMENT EXECUTE FUNCTION public._phase10_event();
CREATE TRIGGER phase10_edge_event AFTER INSERT OR UPDATE ON public.edges FOR EACH STATEMENT EXECUTE FUNCTION public._phase10_event();
CREATE TRIGGER phase10_rendition_event AFTER INSERT OR UPDATE ON public.renditions FOR EACH STATEMENT EXECUTE FUNCTION public._phase10_event();
CREATE OR REPLACE FUNCTION public._phase10_measure_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.type IN('Metric','ValueMeasure') AND (public._rejected_measure(NEW.title||' '||NEW.statement||' '||NEW.body::text) OR NEW.body->>'counts_drafts'='true' OR public._prohibited_inference(NEW.body::text) IS NOT NULL) THEN RAISE EXCEPTION 'MEASURE_REFUSED: outcome measures only; no drafts or individual activity'; END IF; RETURN NEW; END $$;
CREATE TRIGGER phase10_measure_guard BEFORE INSERT OR UPDATE ON public.objects FOR EACH ROW EXECUTE FUNCTION public._phase10_measure_guard();
CREATE OR REPLACE FUNCTION public.phase10_schema_check() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('pass',NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND public._rejected_measure(table_name||' '||column_name)),'checked_at',now()) $$;
CREATE OR REPLACE FUNCTION public.phase10_elapsed_hours(p_start timestamptz,p_end timestamptz) RETURNS numeric LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN p_end>=p_start THEN extract(epoch FROM p_end-p_start)/3600 END $$;
CREATE OR REPLACE FUNCTION public.thread_phase10_selftest() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c record; own uuid; obs uuid; results jsonb:='[]'; ok boolean; BEGIN PERFORM public._phase10_register(); SELECT owner_id INTO own FROM public.detectors LIMIT 1;
BEGIN FOR c IN SELECT * FROM public.detection_catalogue() LOOP INSERT INTO public.detection_observations(owner_id,facts,rationale) VALUES(own,jsonb_build_object(c.fact,true),'Isolated deliberate failure fixture') RETURNING id INTO obs; PERFORM public.thread_detection_sweep('{"kind":"system","id":"phase10-selftest","authority_used":"observe"}'); SELECT EXISTS(SELECT 1 FROM public.detector_findings WHERE detector_key=c.key AND owner_id IS NOT NULL AND evidence->>'observation_id'=obs::text AND state='open') INTO ok; results:=results||jsonb_build_object('name',c.key,'pass',ok,'detail','Explicit evidence observation detected with owner'); UPDATE public.detection_observations SET expires_at=now()-interval '1 second' WHERE id=obs; END LOOP;
results:=results||jsonb_build_object('name','Rejected measure schema','pass',(public.phase10_schema_check()->>'pass')::boolean,'detail','Public fields and tables'); results:=results||jsonb_build_object('name','Intent-to-value arithmetic','pass',public.phase10_elapsed_hours('2026-10-01 12:00Z','2026-10-03 18:00Z')=54,'detail','54 hours'); RAISE EXCEPTION SQLSTATE 'PT010' USING MESSAGE='rollback fixtures'; EXCEPTION WHEN SQLSTATE 'PT010' THEN NULL; END; RETURN jsonb_build_object('passed',NOT EXISTS(SELECT 1 FROM jsonb_array_elements(results) r WHERE r->>'pass'<>'true'),'checks',results,'fixture_mode','explicit_observation; rollback; native graph inductions remain separate'); END $$;
CREATE OR REPLACE FUNCTION public.thread_record_phase10_evidence(p_actor jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ev jsonb; seq bigint; BEGIN PERFORM public._assert_actor(p_actor); IF p_actor->>'kind'<>'human' OR NOT public.has_role((p_actor->>'id')::uuid,'steward') THEN RAISE EXCEPTION 'STEWARD_REQUIRED'; END IF; ev:=public.thread_phase10_selftest(); seq:=public._mcp_ledger(p_actor,'phase10.exit_evidence',NULL,ev); RETURN ev||jsonb_build_object('ledger_seq',seq); END $$;
REVOKE ALL ON FUNCTION public._phase10_register(),public.thread_detection_sweep(jsonb),public.thread_observe_detection(jsonb,uuid,jsonb,uuid[],text),public.thread_resolve_finding(jsonb,uuid,text,timestamptz),public.thread_phase10_selftest(),public.thread_record_phase10_evidence(jsonb),public._phase10_event() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public._phase10_register(),public.thread_detection_sweep(jsonb),public.thread_observe_detection(jsonb,uuid,jsonb,uuid[],text),public.thread_resolve_finding(jsonb,uuid,text,timestamptz),public.thread_phase10_selftest(),public.thread_record_phase10_evidence(jsonb) TO service_role;
REVOKE ALL ON FUNCTION public.detection_candidates(),public.phase10_schema_check() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.detection_candidates(),public.phase10_schema_check() TO authenticated,service_role;
SELECT cron.schedule('thread-phase10-reconcile','0 * * * *',$job$SELECT public.thread_detection_sweep('{"kind":"system","id":"phase10-reconciliation","authority_used":"observe"}'::jsonb);$job$);